contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address adr, uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        uint256 cBalBefore = address(c).balance;
        bool reverted;
        c.multiplicate{value: amount}(adr); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted == (amount < cBalBefore && cBalBefore + amount > uint256(type(uint256).max - cBalBefore)));
    }

    receive() external payable {}
}

